use super::*;

/// Test K-axiom/UIP reduction (#781)
///
/// For K-like types (like Eq), the kernel should reduce any term `h : Eq a a`
/// to the unique constructor `Eq.refl a` when the indices are definitionally equal.
///
/// This test verifies that Eq.rec has is_k = true.
#[test]
fn test_k_axiom_reduction() {
    let mut env = Environment::new();
    env.init_eq().unwrap();

    // Verify that Eq.rec has is_k = true
    let eq_rec = env
        .get_recursor(&Name::from_string("Eq.rec"))
        .expect("Eq.rec should exist");
    assert!(
        eq_rec.is_k,
        "Eq.rec should have is_k = true, but it's false"
    );

    // Also check casesOn and recOn
    let eq_cases_on = env
        .get_recursor(&Name::from_string("Eq.casesOn"))
        .expect("Eq.casesOn should exist");
    assert!(eq_cases_on.is_k, "Eq.casesOn should have is_k = true");

    let eq_rec_on = env
        .get_recursor(&Name::from_string("Eq.recOn"))
        .expect("Eq.recOn should exist");
    assert!(eq_rec_on.is_k, "Eq.recOn should have is_k = true");
}

/// Test Eq.rec iota reduction with Eq.refl
///
/// Eq.rec uses Lean 4-style ordering: params → motive → minors → indices → major.
#[test]
fn test_eq_rec_iota_reduction() {
    let mut env = Environment::new();
    env.init_eq().unwrap();
    env.init_true_false().unwrap();

    // Verify Eq.rec structure matches Lean 4 fixed-index pattern
    let eq_rec = env.get_recursor(&Name::from_string("Eq.rec")).unwrap();
    assert_eq!(
        eq_rec.num_params, 2,
        "Eq.rec num_params (α, a — a promoted from index)"
    );
    assert_eq!(
        eq_rec.num_indices, 1,
        "Eq.rec num_indices (b — only b remains)"
    );
    assert_eq!(eq_rec.num_motives, 1, "Eq.rec num_motives");
    assert_eq!(eq_rec.num_minors, 1, "Eq.rec num_minors");
    assert!(eq_rec.is_k, "Eq.rec is_k should be true");

    let tc = TypeChecker::new(&env);

    // Recursor ordering (MajorAfterMinors):
    // args_before_major = num_params + num_motives + num_minors + num_indices
    //                   = 2 + 1 + 1 + 1 = 5
    // args layout: [param(α), param(a), motive, minor, idx(b), major]

    let prop = Expr::prop();
    let true_const = Expr::const_(Name::from_string("True"), vec![]);

    // Motive: λ (b : α) (_ : Eq a b), True
    // With fixed-index, motive takes 1 index (b) + proof, not 2 indices
    let motive = Expr::lam(
        BinderInfo::Default,
        prop.clone(),
        Expr::lam(BinderInfo::Default, Expr::prop(), true_const.clone()),
    );

    // Minor premise: True.intro (no lambda — refl minor for K-like with fixed a)
    let minor = Expr::const_(Name::from_string("True.intro"), vec![]);

    // Major premise: Eq.refl Prop True (a proof of Eq Prop True True)
    let eq_refl = Expr::const_(
        Name::from_string("Eq.refl"),
        vec![Level::succ(Level::zero())],
    );
    let h = Expr::app(Expr::app(eq_refl, prop.clone()), true_const.clone());

    // Build: Eq.rec α a motive minor b major
    // args = [param(α), param(a), motive, minor, index(b), major(h)]
    let eq_rec_const = Expr::const_(
        Name::from_string("Eq.rec"),
        vec![Level::zero(), Level::succ(Level::zero())],
    );

    let app = Expr::app(
        Expr::app(
            Expr::app(
                Expr::app(
                    Expr::app(
                        Expr::app(eq_rec_const, prop.clone()), // α = Prop (param 0)
                        true_const.clone(),                    // a = True (param 1, promoted)
                    ),
                    motive.clone(), // motive
                ),
                minor.clone(), // minor
            ),
            true_const.clone(), // index (b = True)
        ),
        h, // major (Eq.refl Prop True)
    );

    // WHNF should reduce this to True.intro
    let result = tc.whnf(&app);

    // The result should be True.intro
    assert_eq!(
        result,
        Expr::const_(Name::from_string("True.intro"), vec![]),
        "Eq.rec with Eq.refl should reduce to the base case. Got: {result:?}"
    );
}

/// Regression test: Eq.rec should reduce even when the major proof term is opaque.
///
/// This exercises K-conversion on a non-constructor major premise
/// (`Eq.testOpaqueProof : Eq Nat 0 0`), matching Lean 4's behavior.
#[test]
fn test_eq_rec_iota_reduction_with_opaque_major_proof() {
    use crate::env::Declaration;

    let mut env = Environment::new();
    env.init_nat().unwrap();
    env.init_eq().unwrap();

    let nat = Expr::const_(Name::from_string("Nat"), vec![]);
    let zero = Expr::const_(Name::from_string("Nat.zero"), vec![]);

    // Add an opaque proof constant: Eq.testOpaqueProof : Eq Nat 0 0.
    let eq_const = Expr::const_(Name::from_string("Eq"), vec![Level::succ(Level::zero())]);
    let eq_nat_zero_zero = Expr::app(
        Expr::app(Expr::app(eq_const.clone(), nat.clone()), zero.clone()),
        zero.clone(),
    );
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("Eq.testOpaqueProof"),
        level_params: vec![],
        type_: eq_nat_zero_zero,
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    // motive: λ (x : Nat) (h : Eq Nat 0 x) => Nat
    let motive = Expr::lam(
        BinderInfo::Default,
        nat.clone(),
        Expr::lam(
            BinderInfo::Default,
            Expr::app(
                Expr::app(Expr::app(eq_const, nat.clone()), zero.clone()),
                Expr::bvar(0),
            ),
            nat.clone(),
        ),
    );
    let minor = zero.clone();
    let opaque_major = Expr::const_(Name::from_string("Eq.testOpaqueProof"), vec![]);

    // Eq.rec.{1,1} {Nat} {0} motive minor {0} opaque_major
    let eq_rec = Expr::const_(
        Name::from_string("Eq.rec"),
        vec![Level::succ(Level::zero()), Level::succ(Level::zero())],
    );
    let app = Expr::app(
        Expr::app(
            Expr::app(
                Expr::app(
                    Expr::app(Expr::app(eq_rec, nat.clone()), zero.clone()),
                    motive,
                ),
                minor.clone(),
            ),
            zero,
        ),
        opaque_major,
    );

    assert_eq!(
        tc.whnf(&app),
        minor,
        "Eq.rec should reduce via K-conversion when major proof is opaque"
    );
}

/// ADVERSARIAL (WS7 soundness): K-reduction must NOT fire when the major
/// premise's indices are not definitionally equal.
///
/// `Eq.rec C m b (h : Eq Nat a b)` may only K-reduce to `m` when `a ≡ b`
/// (the unique constructor `Eq.refl` proves `Eq Nat a a`). Here the opaque
/// proof has type `Eq Nat 0 1` — `0` and `1` are distinct constructors and
/// never definitionally equal — so `to_cnstr_when_K` must reject the
/// conversion (its `is_def_eq(e_type, ctor_type)` gate fails) and `whnf` must
/// leave the `Eq.rec` application STUCK rather than collapse it to `m`.
///
/// This is the completeness-vs-soundness boundary for the WS7 `RecursorVal.k`
/// fix: enabling K for `Eq.rec`/`HEq.rec` must never let an ill-formed
/// elimination pass.
#[test]
fn test_eq_rec_k_reduction_rejects_unequal_indices() {
    use crate::env::Declaration;

    let mut env = Environment::new();
    env.init_nat().unwrap();
    env.init_eq().unwrap();

    let nat = Expr::const_(Name::from_string("Nat"), vec![]);
    let zero = Expr::const_(Name::from_string("Nat.zero"), vec![]);
    let one = Expr::app(
        Expr::const_(Name::from_string("Nat.succ"), vec![]),
        zero.clone(),
    );

    // Opaque proof `Eq.bogus : Eq Nat 0 1` (indices NOT definitionally equal).
    let eq_const = Expr::const_(Name::from_string("Eq"), vec![Level::succ(Level::zero())]);
    let eq_nat_zero_one = Expr::app(
        Expr::app(Expr::app(eq_const.clone(), nat.clone()), zero.clone()),
        one.clone(),
    );
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("Eq.bogus"),
        level_params: vec![],
        type_: eq_nat_zero_one,
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    // motive: λ (x : Nat) (h : Eq Nat 0 x) => Nat
    let motive = Expr::lam(
        BinderInfo::Default,
        nat.clone(),
        Expr::lam(
            BinderInfo::Default,
            Expr::app(
                Expr::app(Expr::app(eq_const, nat.clone()), zero.clone()),
                Expr::bvar(0),
            ),
            nat.clone(),
        ),
    );
    let minor = zero.clone();
    let bogus_major = Expr::const_(Name::from_string("Eq.bogus"), vec![]);

    // Eq.rec.{1,1} {Nat} {0} motive minor {1} bogus_major
    let eq_rec = Expr::const_(
        Name::from_string("Eq.rec"),
        vec![Level::succ(Level::zero()), Level::succ(Level::zero())],
    );
    let app = Expr::app(
        Expr::app(
            Expr::app(
                Expr::app(
                    Expr::app(Expr::app(eq_rec, nat.clone()), zero.clone()),
                    motive,
                ),
                minor.clone(),
            ),
            one,
        ),
        bogus_major,
    );

    let reduced = tc.whnf(&app);
    assert_ne!(
        reduced, minor,
        "K-reduction must NOT collapse Eq.rec to the minor premise when the \
         major premise's indices (0 vs 1) are not definitionally equal"
    );
}

