/// Test that structures are not K-like (they have fields)
#[test]
fn test_structure_not_k_like() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();
    env.init_nat().unwrap();

    // Define a simple Pair structure
    let pair_name = Name::from_string("Pair");
    let pair_ref = Expr::const_(pair_name.clone(), vec![]);

    let nat = Expr::const_(Name::from_string("Nat"), vec![]);

    // Pair.mk : Nat → Nat → Pair
    let mk_type = Expr::pi(
        BinderInfo::Default,
        nat.clone(),
        Expr::pi(BinderInfo::Default, nat.clone(), pair_ref.clone()),
    );

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: pair_name.clone(),
            type_: Expr::type_(),
            constructors: vec![Constructor {
                name: Name::from_string("Pair.mk"),
                type_: mk_type,
            }],
        }],
    };

    env.add_inductive(decl).unwrap();

    // Pair has one constructor, but it has fields (not nullary after params)
    // So is_k should be false
    let pair_rec = env
        .get_recursor(&Name::from_string("Pair.rec"))
        .expect("Pair.rec should exist");
    assert!(
        !pair_rec.is_k,
        "Pair.rec should have is_k = false (constructor has fields)"
    );
}

/// Test that phantom-argument inductives are NOT K-like (#1396).
///
/// `Bad4.mk : (phantom : Nat) → Bad4 0` has a constructor arg that does NOT
/// appear in the return type's indices (the index is the literal 0, not BVar
/// referencing phantom). Lean 4's `init_K_target` would reject this because
/// after fixedIndicesToParams, `phantom` is a real field. Previously clean
/// used a weaker `num_ctor_args <= num_indices` check that would incorrectly
/// classify this as K-like — enabling unsound K-reduction.
#[test]
fn test_phantom_arg_not_k_like() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};
    use crate::level::Level;

    let mut env = Environment::new();
    env.init_nat().unwrap();

    let nat = Expr::const_(Name::from_string("Nat"), vec![]);
    let bad_name = Name::from_string("Bad4");
    let bad_const = Expr::const_(bad_name.clone(), vec![]);

    // Bad4 : Nat → Prop
    let bad_type = Expr::pi(
        BinderInfo::Default,
        nat.clone(),
        Expr::from_kind(ExprKind::Sort(Level::zero())),
    );

    // Bad4.mk : (phantom : Nat) → Bad4 0
    // Under 1 binder: phantom = BVar(0)
    // Return type: Bad4 (Nat.zero) — index is Nat.zero, NOT BVar(0)
    let nat_zero = Expr::const_(Name::from_string("Nat.zero"), vec![]);
    let mk_type = Expr::pi(
        BinderInfo::Default,
        nat.clone(),
        Expr::app(bad_const.clone(), nat_zero),
    );

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: bad_name.clone(),
            type_: bad_type,
            constructors: vec![Constructor {
                name: Name::from_string("Bad4.mk"),
                type_: mk_type,
            }],
        }],
    };

    env.add_inductive(decl).unwrap();

    let bad_rec = env
        .get_recursor(&Name::from_string("Bad4.rec"))
        .expect("Bad4.rec should exist");
    assert!(
        !bad_rec.is_k,
        "Bad4.rec should have is_k = false (phantom arg doesn't fill index)"
    );
}

/// Test that a Prop inductive whose constructor arg fills the index IS K-like.
///
/// `Good.mk : (x : Nat) → Good x` — the constructor arg `x` appears directly
/// as the index in the return type. This matches the fixed-index-to-params
/// promotion pattern (like Eq.refl's `a` argument).
#[test]
fn test_fixed_index_arg_is_k_like() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};
    use crate::level::Level;

    let mut env = Environment::new();
    env.init_nat().unwrap();

    let nat = Expr::const_(Name::from_string("Nat"), vec![]);
    let good_name = Name::from_string("Good");
    let good_const = Expr::const_(good_name.clone(), vec![]);

    // Good : Nat → Prop
    let good_type = Expr::pi(
        BinderInfo::Default,
        nat.clone(),
        Expr::from_kind(ExprKind::Sort(Level::zero())),
    );

    // Good.mk : (x : Nat) → Good x
    // Under 1 binder: x = BVar(0)
    // Return type: Good BVar(0) — index IS BVar(0) ✓
    let mk_type = Expr::pi(
        BinderInfo::Default,
        nat.clone(),
        Expr::app(good_const.clone(), Expr::bvar(0)),
    );

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: good_name.clone(),
            type_: good_type,
            constructors: vec![Constructor {
                name: Name::from_string("Good.mk"),
                type_: mk_type,
            }],
        }],
    };

    env.add_inductive(decl).unwrap();

    let good_rec = env
        .get_recursor(&Name::from_string("Good.rec"))
        .expect("Good.rec should exist");
    assert!(
        good_rec.is_k,
        "Good.rec should have is_k = true (ctor arg fills index)"
    );
}

// ============================================================================
// Property-based tests for iota reduction (#1027)
// ============================================================================

use proptest::prelude::*;

/// Build a Nat.rec application with proper typing for property testing.
///
/// Returns (app, env) where app is the Nat.rec application.
fn build_typed_nat_rec(n: usize) -> (Expr, Environment) {
    let mut env = Environment::new();
    env.init_nat().unwrap();

    let nat = Expr::const_(Name::from_string("Nat"), vec![]);

    // Build Nat value: succ^n(zero)
    let mut nat_val = Expr::const_(Name::from_string("Nat.zero"), vec![]);
    for _ in 0..n {
        nat_val = Expr::app(Expr::const_(Name::from_string("Nat.succ"), vec![]), nat_val);
    }

    // Motive: λ (n : Nat). Nat (maps Nat to Nat)
    let motive = Expr::lam(BinderInfo::Default, nat.clone(), nat.clone());

    // Zero case: Nat.zero (value when n = 0)
    let zero_case = Expr::const_(Name::from_string("Nat.zero"), vec![]);

    // Succ case: λ (n : Nat) (ih : Nat). succ ih
    // When we have succ(k), apply succ to the recursive result
    let succ_case = Expr::lam(
        BinderInfo::Default,
        nat.clone(), // n : Nat
        Expr::lam(
            BinderInfo::Default,
            nat.clone(), // ih : Nat (motive n)
            Expr::app(
                Expr::const_(Name::from_string("Nat.succ"), vec![]),
                Expr::bvar(0), // succ ih
            ),
        ),
    );

    // Nat.rec : {motive : Nat → Sort u} → motive zero → ((n : Nat) → motive n → motive (succ n)) → (t : Nat) → motive t
    let nat_rec = Expr::const_(
        Name::from_string("Nat.rec"),
        vec![Level::succ(Level::zero())],
    );

    // Apply: Nat.rec motive zero_case succ_case nat_val
    let app = Expr::app(
        Expr::app(Expr::app(Expr::app(nat_rec, motive), zero_case), succ_case),
        nat_val,
    );

    (app, env)
}

proptest! {
    #![proptest_config(proptest::test_runner::Config::with_cases(32))]

    /// Property: Iota reduction preserves type (#1027)
    ///
    /// ENSURES: If e : T and try_iota_reduction(e) = Some(r), then r : T.
    ///
    /// This tests the type preservation contract documented in tc/mod.rs.
    #[test]
    fn prop_iota_preserves_type(n in 0usize..8) {
        let (app, env) = build_typed_nat_rec(n);
        let tc = TypeChecker::new(&env);

        // Type the original expression
        let original_type = tc.infer_type(&app)
            .expect("Original rec application should be well-typed");

        // Reduce to WHNF (which applies iota reduction)
        let reduced = tc.whnf(&app);

        // Type the reduced expression
        let reduced_type = tc.infer_type(&reduced)
            .expect("Reduced expression should be well-typed");

        // Types must be definitionally equal
        prop_assert!(
            tc.is_def_eq(&original_type, &reduced_type),
            "Type preservation violated: \
             original type {:?} != reduced type {:?} for n={}",
            original_type, reduced_type, n
        );
    }

    /// Property: Iota reduction produces definitionally equal result (#1027)
    ///
    /// ENSURES: If try_iota_reduction(e) = Some(r), then e ≡ r.
    ///
    /// This is semantic preservation: the recursor application and its
    /// reduced form are definitionally equal.
    #[test]
    fn prop_iota_semantic_preservation(n in 0usize..8) {
        let (app, env) = build_typed_nat_rec(n);
        let tc = TypeChecker::new(&env);

        // Get WHNF (applies iota reduction internally)
        let reduced = tc.whnf(&app);

        // The original and reduced should be definitionally equal
        prop_assert!(
            tc.is_def_eq(&app, &reduced),
            "Semantic preservation violated: rec app not def_eq to reduced form for n={}",
            n
        );
    }

    /// Property: Nat.rec computes correct value (specification test)
    ///
    /// For our identity-like recursor (rec n = n), verify the computed
    /// value equals the input. This tests the actual computation, not just
    /// type preservation.
    #[test]
    fn prop_nat_rec_computes_identity(n in 0usize..8) {
        let (app, env) = build_typed_nat_rec(n);
        let tc = TypeChecker::new(&env);

        // Reduce to WHNF
        let reduced = tc.whnf(&app);

        // Build expected result: succ^n(zero) (same as input since our rec computes identity)
        let mut expected = Expr::const_(Name::from_string("Nat.zero"), vec![]);
        for _ in 0..n {
            expected = Expr::app(
                Expr::const_(Name::from_string("Nat.succ"), vec![]),
                expected,
            );
        }

        // Result should be definitionally equal to expected
        prop_assert!(
            tc.is_def_eq(&reduced, &expected),
            "Nat.rec {} did not reduce to expected succ^{}(zero). Got: {:?}",
            n, n, reduced
        );
    }
}

/// Test iota reduction with both argument order modes (#1027)
///
/// Verifies that both `MajorAfterMinors` (standard Nat.rec) and
/// `MajorAfterMotive` (recOn style) produce correct results.
#[test]
fn test_iota_both_arg_orders() {
    let mut env = Environment::new();
    env.init_nat().unwrap();

    let tc = TypeChecker::new(&env);

    // Test MajorAfterMinors (Nat.rec)
    let nat_rec = env
        .get_recursor(&Name::from_string("Nat.rec"))
        .expect("Nat.rec should exist");
    assert_eq!(
        nat_rec.arg_order,
        crate::inductive::RecursorArgOrder::MajorAfterMinors,
        "Nat.rec should use MajorAfterMinors"
    );

    // Test MajorAfterMotive (Nat.recOn)
    let nat_rec_on = env
        .get_recursor(&Name::from_string("Nat.recOn"))
        .expect("Nat.recOn should exist");
    assert_eq!(
        nat_rec_on.arg_order,
        crate::inductive::RecursorArgOrder::MajorAfterMotive,
        "Nat.recOn should use MajorAfterMotive"
    );

    // Build test: both should reduce succ(zero) correctly
    let nat = Expr::const_(Name::from_string("Nat"), vec![]);
    let nat_val = Expr::app(
        Expr::const_(Name::from_string("Nat.succ"), vec![]),
        Expr::const_(Name::from_string("Nat.zero"), vec![]),
    ); // succ(zero) = 1

    // Motive: λ (n : Nat). Nat
    let motive = Expr::lam(BinderInfo::Default, nat.clone(), nat.clone());

    // Zero case: zero
    let zero_case = Expr::const_(Name::from_string("Nat.zero"), vec![]);

    // Succ case: λ n ih. succ ih
    let succ_case = Expr::lam(
        BinderInfo::Default,
        nat.clone(),
        Expr::lam(
            BinderInfo::Default,
            nat.clone(),
            Expr::app(
                Expr::const_(Name::from_string("Nat.succ"), vec![]),
                Expr::bvar(0),
            ),
        ),
    );

    // Nat.rec motive zero_case succ_case nat_val (MajorAfterMinors)
    let rec_app = Expr::app(
        Expr::app(
            Expr::app(
                Expr::app(
                    Expr::const_(
                        Name::from_string("Nat.rec"),
                        vec![Level::succ(Level::zero())],
                    ),
                    motive.clone(),
                ),
                zero_case.clone(),
            ),
            succ_case.clone(),
        ),
        nat_val.clone(),
    );

    // Nat.recOn motive nat_val zero_case succ_case (MajorAfterMotive)
    let rec_on_app = Expr::app(
        Expr::app(
            Expr::app(
                Expr::app(
                    Expr::const_(
                        Name::from_string("Nat.recOn"),
                        vec![Level::succ(Level::zero())],
                    ),
                    motive.clone(),
                ),
                nat_val.clone(),
            ),
            zero_case,
        ),
        succ_case,
    );

    // Both should reduce to succ(zero)
    let expected = Expr::app(
        Expr::const_(Name::from_string("Nat.succ"), vec![]),
        Expr::const_(Name::from_string("Nat.zero"), vec![]),
    );

    let rec_result = tc.whnf(&rec_app);
    let rec_on_result = tc.whnf(&rec_on_app);

    assert!(
        tc.is_def_eq(&rec_result, &expected),
        "Nat.rec with MajorAfterMinors failed: {:?}",
        rec_result
    );
    assert!(
        tc.is_def_eq(&rec_on_result, &expected),
        "Nat.recOn with MajorAfterMotive failed: {:?}",
        rec_on_result
    );
}

