/// And : Prop → Prop → Prop with 1 constructor but 2 fields and 0 indices.
/// K requires indices > 0, so And should NOT be K-like.
#[test]
fn test_and_not_k_like() {
    let mut env = Environment::new();
    env.init_and().unwrap();

    let and_rec = env
        .get_recursor(&Name::from_string("And.rec"))
        .expect("And.rec should exist");
    assert!(
        !and_rec.is_k,
        "And.rec should have is_k = false (no indices)"
    );

    let and_cases = env
        .get_recursor(&Name::from_string("And.casesOn"))
        .expect("And.casesOn should exist");
    assert!(
        !and_cases.is_k,
        "And.casesOn should have is_k = false (no indices)"
    );
}

/// Unit : Type with 1 constructor, 0 fields, but NOT in Prop.
/// K requires the type to be in Prop, so Unit should NOT be K-like.
/// Unit is now a reducible definition for PUnit.{1} (#3418), so there is no
/// Unit.rec. Instead we test that PUnit.rec (which Unit delegates to) is not
/// K-like. PUnit.{u} : Sort u lives outside Prop for u >= 1.
#[test]
fn test_punit_not_k_like() {
    let mut env = Environment::new();
    env.init_unit().unwrap(); // also initializes PUnit

    let punit_rec = env
        .get_recursor(&Name::from_string("PUnit.rec"))
        .expect("PUnit.rec should exist");
    assert!(
        !punit_rec.is_k,
        "PUnit.rec should have is_k = false (PUnit lives in Sort u, not Prop)"
    );
}

/// True : Prop with 1 constructor (True.intro), 0 fields, and 0 indices.
/// Lean 4's init_K_target accepts this: in Prop, 1 ctor, 0 fields beyond params.
/// K-reduction for True is equivalent to standard iota, but Lean 4 marks it K.
#[test]
fn test_true_is_k_like() {
    let mut env = Environment::new();
    env.init_eq().unwrap(); // Ne (defined in init_true_false) depends on Eq
    env.init_true_false().unwrap();

    let true_rec = env
        .get_recursor(&Name::from_string("True.rec"))
        .expect("True.rec should exist");
    assert!(
        true_rec.is_k,
        "True.rec should have is_k = true (Prop, 1 ctor, 0 fields — matches Lean 4)"
    );
}

/// Or : Prop → Prop → Prop with 2 constructors (inl, inr).
/// K requires exactly 1 constructor, so Or should NOT be K-like.
#[test]
fn test_or_not_k_like() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();

    let or_name = Name::from_string("Or");

    // Or : Prop → Prop → Prop
    let or_type = Expr::pi(
        BinderInfo::Default,
        Expr::prop(),
        Expr::pi(BinderInfo::Default, Expr::prop(), Expr::prop()),
    );

    // Or.inl : (P Q : Prop) → P → Or P Q
    let inl_type = Expr::pi(
        BinderInfo::Default,
        Expr::prop(),
        Expr::pi(
            BinderInfo::Default,
            Expr::prop(),
            Expr::pi(
                BinderInfo::Default,
                Expr::bvar(1), // proof of P
                Expr::app(
                    Expr::app(Expr::const_(or_name.clone(), vec![]), Expr::bvar(2)),
                    Expr::bvar(1),
                ),
            ),
        ),
    );

    // Or.inr : (P Q : Prop) → Q → Or P Q
    let inr_type = Expr::pi(
        BinderInfo::Default,
        Expr::prop(),
        Expr::pi(
            BinderInfo::Default,
            Expr::prop(),
            Expr::pi(
                BinderInfo::Default,
                Expr::bvar(0), // proof of Q
                Expr::app(
                    Expr::app(Expr::const_(or_name.clone(), vec![]), Expr::bvar(2)),
                    Expr::bvar(1),
                ),
            ),
        ),
    );

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 2,
        types: vec![InductiveType {
            name: or_name,
            type_: or_type,
            constructors: vec![
                Constructor {
                    name: Name::from_string("Or.inl"),
                    type_: inl_type,
                },
                Constructor {
                    name: Name::from_string("Or.inr"),
                    type_: inr_type,
                },
            ],
        }],
    };

    env.add_inductive(decl).unwrap();

    let or_rec = env
        .get_recursor(&Name::from_string("Or.rec"))
        .expect("Or.rec should exist");
    assert!(
        !or_rec.is_k,
        "Or.rec should have is_k = false (2 constructors)"
    );
}

